# Fetch current venmo friends to get their emails
venmo_friends = []
page_index = 0
while True:
    resp = apis.venmo.search_friends(access_token=venmo_token, page_index=page_index, page_limit=20)
    if 'friends' in resp:
        venmo_friends.extend(resp['friends'])
        if len(resp['friends']) < 20:
            break
        page_index += 1
    else:
        print("Error:", resp)
        break

for f in venmo_friends:
    print(f['first_name'], f['last_name'], f['email'])

# The response is a list directly, not wrapped in 'friends' key. Let's re-fetch properly.
venmo_friends = []
page_index = 0
while True:
    resp = apis.venmo.search_friends(access_token=venmo_token, page_index=page_index, page_limit=20)
    if isinstance(resp, list):
        venmo_friends.extend(resp)
        if len(resp) < 20:
            break
        page_index += 1
    else:
        print("Unexpected response:", resp)
        break

print("Total venmo friends:", len(venmo_friends))
for f in venmo_friends:
    print(f['first_name'], f['last_name'], f['email'])

