    519: [22, 44, 111, 146, 226, 265, 287, 294, 298]
}

for pid, songs in playlist_songs.items():
    for song_id in songs:
        if song_id in target_songs:
            result = apis.spotify.remove_song_from_playlist(playlist_id=pid, song_id=song_id, access_token=spotify_token)
            print(f"Removed song {song_id} from playlist {pid}: {result}")

