  {
   "name": "pinned",
   "type": "boolean",
   "required": false,
   "description": "Updated pinned status of the note.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string"
  },
  "failure": {
   "message": "string"
  }
 }
