steps.code:
# Remove liked songs from queue, starting from highest position to avoid index shifting
liked_song_ids = {19, 103, 109, 133, 135, 167, 204, 206, 229, 242, 301}
# Get positions of liked songs in current queue
positions_to_remove = []
for i, song in enumerate(queue):
    if song['song_id'] in liked_song_ids:
        positions_to_remove.append(i)

# Sort descending to remove from end first
positions_to_remove.sort(reverse=True)
print(f"Positions to remove: {positions_to_remove}")

for pos in positions_to_remove:
    result = apis.spotify.remove_song_from_queue(position=pos, access_token=access_token)
    print(f"Removed position {pos}: {result}")

